pub enum ArmBudget { Within, Exceeds, ReferenceUndecidable }
pub fn classify_arm_budget(e: f64, u: f64, budget: f64) -> FairResult<ArmBudget> {
    if !(e.is_finite() && u.is_finite() && budget.is_finite() && e >= 0.0 && u >= 0.0 && budget > 0.0) {
        return Err(FairError::Invalid("arm budget inputs must be finite and nonnegative".into()));
    }
    Ok(if e + u <= budget { ArmBudget::Within }
       else if e - u > budget { ArmBudget::Exceeds }
       else { ArmBudget::ReferenceUndecidable })
}
pub fn assert_gap_triangle(gap: f64, e_c: f64, e_d: f64) -> FairResult<()> {
    // identity through y_ref; violation == grid/weight misalignment, not science
    if gap > (e_c + e_d) * (1.0 + 64.0 * f64::EPSILON) {
        return Err(FairError::Invalid("policy gap violates triangle identity".into()));
    }
    Ok(())
}
pub fn classify_row(c: ArmBudget, d: ArmBudget, delta_same_step: f64, local_budget: f64) -> V2RowStatus {
    use ArmBudget::*;
    match (c, d) {
        (ReferenceUndecidable, _) | (_, ReferenceUndecidable) => V2RowStatus::ReferenceDominated,
        (Exceeds, _) | (_, Exceeds) => V2RowStatus::GlobalErrorExceedsBudget,
        _ if delta_same_step > local_budget => V2RowStatus::InterpolantDominated,
        _ => V2RowStatus::Pass,
    }
}

const CLIP_INFORMATIVE_RATIO: f64 = 0.5;
if accepted {
    let sample = error.max(1.0e-16);
    // factor must be proposed BEFORE the sample is recorded (PI needs the older error)
    let factor = controller.propose_factor(config, sample, estimator_order, true)?;
    if !forced_output_clipped {
        controller.record_acceptance(error)?;
        return Ok(trial_h * factor);
    }
    let candidate = trial_h * factor;
    let ratio = trial_h / requested_h;          // (0, 1) on a clipped trial
    if ratio >= CLIP_INFORMATIVE_RATIO {
        controller.record_acceptance(error)?;
        let predicted = sample * ratio.powf(-(estimator_order as f64));
        if predicted > 1.0 {
            // remembered request would be rejected: shrink, never below the accepted trial
            return Ok(candidate.max(trial_h).min(requested_h));
        }
    }
    // remembered pre-clip request survives; an informative sample may only raise it
    return Ok(requested_h.max(candidate));
}

pub struct BasisTaggedMetrics {
    pub basis_id: String,            // e.g. "case-tolerance;atol=1e-6;rtol=1e-4;anchor=reference"
    pub metrics: GlobalErrorMetrics,
}
impl ReferenceWrmsBasis {
    pub fn with_case_tolerance(&self, atol: f64, rtol: f64) -> FairResult<Self> {
        let mut basis = self.clone();
        let ratio = basis.error_scale.worst_weight_ratio(atol, rtol, &self.reference_states)?;
        basis.error_scale.reference_uncertainty_wrms *= ratio; // max_j w_tight_j / w_case_j
        basis.error_scale.absolute.iter_mut().for_each(|a| *a = atol);
        basis.error_scale.relative = rtol;
        Ok(basis)
    }
}
